import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing a row-quad-per-block GEMV:
#   C[row] = sum_k A[row, k] * B[k]
#
# One CUDA block handles FOUR rows of A cooperatively (row-quad tiling).
# Compared to a row-pair scheme, this halves the number of CTAs launched
# for a given M, which in turn halves the number of times the (heavily
# reused) B vector is streamed from global memory across the whole grid,
# improving effective memory-bandwidth utilization since this kernel is
# bandwidth bound (A is huge: M x K x 4 bytes). Threads stride over K using
# vectorized 128-bit (float4) cp.async double-buffered loads for both A and
# B. A scalar tail loop handles any remaining elements when K is not a
# multiple of 4. Warp-level shuffle reduction followed by a block-level
# reduction (through shared memory) produces the four final scalars.
# Fallback TRIPLE/DOUBLE/SINGLE row paths handle the tail block when M is
# not an exact multiple of 4.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64
.visible .entry gemv_kernel(
    .param .u64 gemv_kernel_param_0,
    .param .u64 gemv_kernel_param_1,
    .param .u64 gemv_kernel_param_2,
    .param .u32 gemv_kernel_param_3,
    .param .u32 gemv_kernel_param_4
)
{
    .reg .pred %p<40>;
    .reg .f32  %f<260>;
    .reg .b32  %r<230>;
    .reg .b64  %rd<180>;
    // Four shared arrays hold per-warp partial sums for the four rows
    // processed cooperatively by this CTA (row-quad tiling). This
    // amortizes the redundant re-reads of the B vector (which is shared
    // by all rows of A) across 4 rows per CTA instead of 2, roughly
    // halving the number of CTAs (and therefore the number of times B is
    // streamed from global memory) compared to the previous row-pair
    // tiling scheme.
    .shared .align 4 .b8 warp_sums0[128];
    .shared .align 4 .b8 warp_sums1[128];
    .shared .align 4 .b8 warp_sums2[128];
    .shared .align 4 .b8 warp_sums3[128];
    .shared .align 16 .b8 bufA0[8192];
    .shared .align 16 .b8 bufA1[8192];
    .shared .align 16 .b8 bufA2[8192];
    .shared .align 16 .b8 bufA3[8192];
    .shared .align 16 .b8 bufB[8192];
    ld.param.u64 %rd1, [gemv_kernel_param_0];   // A ptr
    ld.param.u64 %rd2, [gemv_kernel_param_1];   // B ptr
    ld.param.u64 %rd3, [gemv_kernel_param_2];   // C ptr
    ld.param.u32 %r1,  [gemv_kernel_param_3];   // M
    ld.param.u32 %r2,  [gemv_kernel_param_4];   // K
    cvta.to.global.u64 %rd4, %rd1;
    cvta.to.global.u64 %rd5, %rd2;
    cvta.to.global.u64 %rd6, %rd3;
    mov.u32 %r3, %ctaid.x;                 // block id
    shl.b32 %r30, %r3, 2;                  // row0 = blockIdx.x * 4
    setp.ge.s32 %p1, %r30, %r1;
    @%p1 bra DONE;
    add.s32 %r31, %r30, 1;                 // row1
    add.s32 %r60, %r30, 2;                 // row2
    add.s32 %r61, %r30, 3;                 // row3
    setp.ge.s32 %p2, %r31, %r1;            // only row0 valid
    @%p2 bra SINGLE;
    setp.ge.s32 %p3, %r60, %r1;            // only row0,row1 valid
    @%p3 bra DOUBLE;
    setp.ge.s32 %p4, %r61, %r1;            // only row0,row1,row2 valid
    @%p4 bra TRIPLE;
    bra QUAD;
QUAD:
    mov.u32 %r100, %tid.x;
    mov.u32 %r101, %ntid.x;
    mul.wide.u32 %rd100, %r30, %r2;
    shl.b64 %rd101, %rd100, 2;
    add.s64 %rd102, %rd4, %rd101;          // A0 base (row0)
    mul.wide.u32 %rd103, %r31, %r2;
    shl.b64 %rd104, %rd103, 2;
    add.s64 %rd105, %rd4, %rd104;          // A1 base (row1)
    mul.wide.u32 %rd106, %r60, %r2;
    shl.b64 %rd107, %rd106, 2;
    add.s64 %rd108, %rd4, %rd107;          // A2 base (row2)
    mul.wide.u32 %rd109, %r61, %r2;
    shl.b64 %rd110, %rd109, 2;
    add.s64 %rd111, %rd4, %rd110;          // A3 base (row3)
    mov.f32 %f100, 0f00000000;
    mov.f32 %f101, 0f00000000;
    mov.f32 %f102, 0f00000000;
    mov.f32 %f103, 0f00000000;
    shr.u32 %r102, %r2, 2;                 // vec_K
    mov.u32 %r103, %r100;                  // vi = tid
    mov.u32 %r110, bufA0;
    mov.u32 %r111, bufA1;
    mov.u32 %r112, bufA2;
    mov.u32 %r113, bufA3;
    mov.u32 %r114, bufB;
    shl.b32 %r115, %r100, 4;               // tid * 16
    add.s32 %r120, %r110, %r115;
    add.s32 %r121, %r111, %r115;
    add.s32 %r122, %r112, %r115;
    add.s32 %r123, %r113, %r115;
    add.s32 %r124, %r114, %r115;
    mov.u32 %r130, 0;                      // stage
    setp.lt.s32 %p20, %r103, %r102;
    mul.wide.u32 %rd120, %r103, 16;
    add.s64 %rd121, %rd102, %rd120;
    add.s64 %rd122, %rd105, %rd120;
    add.s64 %rd123, %rd108, %rd120;
    add.s64 %rd124, %rd111, %rd120;
    add.s64 %rd125, %rd5,  %rd120;
    @!%p20 bra Q_PRO_SKIP;
    cp.async.cg.shared.global [%r120], [%rd121], 16;
    cp.async.cg.shared.global [%r121], [%rd122], 16;
    cp.async.cg.shared.global [%r122], [%rd123], 16;
    cp.async.cg.shared.global [%r123], [%rd124], 16;
    cp.async.ca.shared.global [%r124], [%rd125], 16;
Q_PRO_SKIP:
    cp.async.commit_group;
Q_VLOOP:
    @!%p20 bra Q_VLOOP_END;
    add.s32 %r140, %r103, %r101;
    setp.lt.s32 %p21, %r140, %r102;
    xor.b32 %r141, %r130, 1;
    mul.lo.s32 %r142, %r141, 4096;
    add.s32 %r150, %r120, %r142;
    add.s32 %r151, %r121, %r142;
    add.s32 %r152, %r122, %r142;
    add.s32 %r153, %r123, %r142;
    add.s32 %r154, %r124, %r142;
    mul.wide.u32 %rd130, %r140, 16;
    add.s64 %rd131, %rd102, %rd130;
    add.s64 %rd132, %rd105, %rd130;
    add.s64 %rd133, %rd108, %rd130;
    add.s64 %rd134, %rd111, %rd130;
    add.s64 %rd135, %rd5,  %rd130;
    @!%p21 bra Q_ISSUE_SKIP;
    cp.async.cg.shared.global [%r150], [%rd131], 16;
    cp.async.cg.shared.global [%r151], [%rd132], 16;
    cp.async.cg.shared.global [%r152], [%rd133], 16;
    cp.async.cg.shared.global [%r153], [%rd134], 16;
    cp.async.ca.shared.global [%r154], [%rd135], 16;
Q_ISSUE_SKIP:
    cp.async.commit_group;
    cp.async.wait_group 1;
    mul.lo.s32 %r160, %r130, 4096;
    add.s32 %r161, %r120, %r160;
    add.s32 %r162, %r121, %r160;
    add.s32 %r163, %r122, %r160;
    add.s32 %r164, %r123, %r160;
    add.s32 %r165, %r124, %r160;
    ld.shared.v4.f32 {%f200,%f201,%f202,%f203}, [%r161];
    ld.shared.v4.f32 {%f204,%f205,%f206,%f207}, [%r162];
    ld.shared.v4.f32 {%f208,%f209,%f210,%f211}, [%r163];
    ld.shared.v4.f32 {%f212,%f213,%f214,%f215}, [%r164];
    ld.shared.v4.f32 {%f216,%f217,%f218,%f219}, [%r165];
    fma.rn.f32 %f100, %f200, %f216, %f100;
    fma.rn.f32 %f100, %f201, %f217, %f100;
    fma.rn.f32 %f100, %f202, %f218, %f100;
    fma.rn.f32 %f100, %f203, %f219, %f100;
    fma.rn.f32 %f101, %f204, %f216, %f101;
    fma.rn.f32 %f101, %f205, %f217, %f101;
    fma.rn.f32 %f101, %f206, %f218, %f101;
    fma.rn.f32 %f101, %f207, %f219, %f101;
    fma.rn.f32 %f102, %f208, %f216, %f102;
    fma.rn.f32 %f102, %f209, %f217, %f102;
    fma.rn.f32 %f102, %f210, %f218, %f102;
    fma.rn.f32 %f102, %f211, %f219, %f102;
    fma.rn.f32 %f103, %f212, %f216, %f103;
    fma.rn.f32 %f103, %f213, %f217, %f103;
    fma.rn.f32 %f103, %f214, %f218, %f103;
    fma.rn.f32 %f103, %f215, %f219, %f103;
    mov.u32 %r103, %r140;
    mov.u32 %r130, %r141;
    mov.pred %p20, %p21;
    bra Q_VLOOP;
Q_VLOOP_END:
    cp.async.wait_group 0;
    mul.lo.s32 %r170, %r102, 4;
    add.s32 %r171, %r170, %r100;
Q_TLOOP:
    setp.ge.s32 %p22, %r171, %r2;
    @%p22 bra Q_TLOOP_END;
    mul.wide.u32 %rd140, %r171, 4;
    add.s64 %rd141, %rd102, %rd140;
    add.s64 %rd142, %rd105, %rd140;
    add.s64 %rd143, %rd108, %rd140;
    add.s64 %rd144, %rd111, %rd140;
    add.s64 %rd145, %rd5,  %rd140;
    ld.global.f32 %f220, [%rd141];
    ld.global.f32 %f221, [%rd142];
    ld.global.f32 %f222, [%rd143];
    ld.global.f32 %f223, [%rd144];
    ld.global.f32 %f224, [%rd145];
    fma.rn.f32 %f100, %f220, %f224, %f100;
    fma.rn.f32 %f101, %f221, %f224, %f101;
    fma.rn.f32 %f102, %f222, %f224, %f102;
    fma.rn.f32 %f103, %f223, %f224, %f103;
    add.s32 %r171, %r171, %r101;
    bra Q_TLOOP;
Q_TLOOP_END:
    mov.b32 %r180, %f100;
    shfl.sync.down.b32 %r181|%p23, %r180, 16, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f100, %f100, %f230;
    mov.b32 %r180, %f100;
    shfl.sync.down.b32 %r181|%p23, %r180, 8, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f100, %f100, %f230;
    mov.b32 %r180, %f100;
    shfl.sync.down.b32 %r181|%p23, %r180, 4, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f100, %f100, %f230;
    mov.b32 %r180, %f100;
    shfl.sync.down.b32 %r181|%p23, %r180, 2, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f100, %f100, %f230;
    mov.b32 %r180, %f100;
    shfl.sync.down.b32 %r181|%p23, %r180, 1, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f100, %f100, %f230;
    mov.b32 %r180, %f101;
    shfl.sync.down.b32 %r181|%p23, %r180, 16, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f101, %f101, %f230;
    mov.b32 %r180, %f101;
    shfl.sync.down.b32 %r181|%p23, %r180, 8, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f101, %f101, %f230;
    mov.b32 %r180, %f101;
    shfl.sync.down.b32 %r181|%p23, %r180, 4, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f101, %f101, %f230;
    mov.b32 %r180, %f101;
    shfl.sync.down.b32 %r181|%p23, %r180, 2, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f101, %f101, %f230;
    mov.b32 %r180, %f101;
    shfl.sync.down.b32 %r181|%p23, %r180, 1, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f101, %f101, %f230;
    mov.b32 %r180, %f102;
    shfl.sync.down.b32 %r181|%p23, %r180, 16, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f102, %f102, %f230;
    mov.b32 %r180, %f102;
    shfl.sync.down.b32 %r181|%p23, %r180, 8, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f102, %f102, %f230;
    mov.b32 %r180, %f102;
    shfl.sync.down.b32 %r181|%p23, %r180, 4, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f102, %f102, %f230;
    mov.b32 %r180, %f102;
    shfl.sync.down.b32 %r181|%p23, %r180, 2, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f102, %f102, %f230;
    mov.b32 %r180, %f102;
    shfl.sync.down.b32 %r181|%p23, %r180, 1, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f102, %f102, %f230;
    mov.b32 %r180, %f103;
    shfl.sync.down.b32 %r181|%p23, %r180, 16, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f103, %f103, %f230;
    mov.b32 %r180, %f103;
    shfl.sync.down.b32 %r181|%p23, %r180, 8, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f103, %f103, %f230;
    mov.b32 %r180, %f103;
    shfl.sync.down.b32 %r181|%p23, %r180, 4, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f103, %f103, %f230;
    mov.b32 %r180, %f103;
    shfl.sync.down.b32 %r181|%p23, %r180, 2, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f103, %f103, %f230;
    mov.b32 %r180, %f103;
    shfl.sync.down.b32 %r181|%p23, %r180, 1, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f103, %f103, %f230;
    and.b32 %r190, %r100, 31;
    shr.u32 %r191, %r100, 5;
    setp.ne.s32 %p25, %r190, 0;
    @%p25 bra Q_SKIP_STORE;
    mov.u32 %r192, warp_sums0;
    shl.b32 %r193, %r191, 2;
    add.s32 %r194, %r192, %r193;
    st.shared.f32 [%r194], %f100;
    mov.u32 %r195, warp_sums1;
    add.s32 %r196, %r195, %r193;
    st.shared.f32 [%r196], %f101;
    mov.u32 %r197, warp_sums2;
    add.s32 %r198, %r197, %r193;
    st.shared.f32 [%r198], %f102;
    mov.u32 %r199, warp_sums3;
    add.s32 %r200, %r199, %r193;
    st.shared.f32 [%r200], %f103;
Q_SKIP_STORE:
    bar.sync 0;
    setp.ne.s32 %p26, %r191, 0;
    @%p26 bra DONE;
    shr.u32 %r201, %r101, 5;
    mov.f32 %f240, 0f00000000;
    mov.f32 %f241, 0f00000000;
    mov.f32 %f242, 0f00000000;
    mov.f32 %f243, 0f00000000;
    setp.ge.u32 %p27, %r190, %r201;
    @%p27 bra Q_SKIP_LOAD;
    mov.u32 %r202, warp_sums0;
    shl.b32 %r203, %r190, 2;
    add.s32 %r204, %r202, %r203;
    ld.shared.f32 %f240, [%r204];
    mov.u32 %r205, warp_sums1;
    add.s32 %r206, %r205, %r203;
    ld.shared.f32 %f241, [%r206];
    mov.u32 %r207, warp_sums2;
    add.s32 %r208, %r207, %r203;
    ld.shared.f32 %f242, [%r208];
    mov.u32 %r209, warp_sums3;
    add.s32 %r210, %r209, %r203;
    ld.shared.f32 %f243, [%r210];
Q_SKIP_LOAD:
    mov.b32 %r180, %f240;
    shfl.sync.down.b32 %r181|%p23, %r180, 16, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f240, %f240, %f230;
    mov.b32 %r180, %f240;
    shfl.sync.down.b32 %r181|%p23, %r180, 8, 31, -1;
    mov.b32 %f230, %r181;
    add.f32 %f240, %f240, %f230;
    mov.b32 %r180, %f240;
